            total += sign * val[ch - 'a'];
            sign = 1;
            ++i;
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Q;
    cin >> Q;
    while (Q--) {
        int n;
        string E;
        cin >> n >> E;

        fill(val, val + 26, 0);                          // 每道题的变量表都要清干净
        for (int i = 0; i < n; ++i) {
            string s;
            cin >> s;                                    // 形如 a=10 或 a=-5
            size_t p = s.find('=');
            val[s[0] - 'a'] = stoi(s.substr(p + 1));     // stoi 认负号
        }

        size_t p = E.find('=');                          // 按等号切成左右两边，分别求值
        long long L = eval(E.substr(0, p));
        long long R = eval(E.substr(p + 1));
